import{_ as e,a,b as o}from"./chunks/modrinth-stafflist.BpTTh3na.js";import{_ as r,o as n,c as l,a2 as s}from"./chunks/framework.CC9cRD7J.js";const b=JSON.parse('{"title":"Gadgets de la Hotbar","description":"","frontmatter":{},"headers":[],"relativePath":"modo-staff/herramientas-hotbar.md","filePath":"modo-staff/herramientas-hotbar.md","lastUpdated":1793575741000}'),d={name:"modo-staff/herramientas-hotbar.md"};function i(c,t,g,u,p,m){return n(),l("div",null,[...t[0]||(t[0]=[s('<h1 id="gadgets-de-la-hotbar" tabindex="-1">Gadgets de la Hotbar <a class="header-anchor" href="#gadgets-de-la-hotbar" aria-label="Permalink to &quot;Gadgets de la Hotbar&quot;">​</a></h1><p><img src="'+e+'" alt="Barra de Herramientas del Modo Staff"></p><p>Cuando un moderador ingresa al Modo Staff, su barra de acceso rápido se equipa con las siguientes herramientas interactivas:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Slot</th><th style="text-align:left;">Objeto</th><th style="text-align:left;">Nombre</th><th style="text-align:left;">Función Principal</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td style="text-align:left;"><code>COMPASS</code></td><td style="text-align:left;"><strong>Propulsor (Launcher)</strong></td><td style="text-align:left;">Impulsa al moderador en la dirección en que está mirando a gran velocidad.</td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td style="text-align:left;"><code>ENDER_EYE</code></td><td style="text-align:left;"><strong>Teleport Aleatorio (RTP)</strong></td><td style="text-align:left;">Teletransporta instantáneamente al moderador hacia un jugador aleatorio sin lanzar proyectiles.</td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td style="text-align:left;"><code>INK_SAC</code></td><td style="text-align:left;"><strong>Alternar Vanish</strong></td><td style="text-align:left;">Activa o desactiva la invisibilidad total con un clic derecho.</td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:left;"><code>PAPER</code></td><td style="text-align:left;"><strong>Centro de GUIs (GUI Hub)</strong></td><td style="text-align:left;">Abre el panel con los reportes pendientes de resolución y jugadores minando bajo tierra.</td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td style="text-align:left;"><code>PLAYER_HEAD</code></td><td style="text-align:left;"><strong>Lista de Staff</strong></td><td style="text-align:left;">Muestra qué miembros del staff están conectados y cuántos están en modo servicio.</td></tr><tr><td style="text-align:center;"><strong>6</strong></td><td style="text-align:left;"><code>BLAZE_ROD</code></td><td style="text-align:left;"><strong>Congelar (Freeze)</strong></td><td style="text-align:left;">Hace clic derecho sobre un jugador sospechoso para paralizarlo al instante.</td></tr><tr><td style="text-align:center;"><strong>7</strong></td><td style="text-align:left;"><code>CLOCK</code></td><td style="text-align:left;"><strong>Test de CPS</strong></td><td style="text-align:left;">Inicia una prueba de velocidad de clics sobre el jugador objetivo durante 10 segundos.</td></tr><tr><td style="text-align:center;"><strong>8</strong></td><td style="text-align:left;"><code>CHEST</code></td><td style="text-align:left;"><strong>Examinar Inventario</strong></td><td style="text-align:left;">Abre la interfaz de inspección completa del jugador (inventario, armadura, ping, IP, etc.).</td></tr><tr><td style="text-align:center;"><strong>9</strong></td><td style="text-align:left;"><code>LEAD</code></td><td style="text-align:left;"><strong>Seguir / Montar (Follow)</strong></td><td style="text-align:left;">Monta de forma invisible sobre el jugador para seguir sus movimientos en primera persona.</td></tr></tbody></table><hr><h2 id="🧭-1-propulsor-compass" tabindex="-1">🧭 1. Propulsor (Compass) <a class="header-anchor" href="#🧭-1-propulsor-compass" aria-label="Permalink to &quot;🧭 1. Propulsor (Compass)&quot;">​</a></h2><ul><li><strong>Acción:</strong> Clic derecho apuntando en cualquier dirección.</li><li><strong>Comportamiento:</strong> Aplica un vector de velocidad hacia adelante para recorrer grandes distancias de manera rápida.</li><li><strong>Configuración:</strong> La velocidad se gradúa en <code>config.yml</code> con la clave <code>velocity</code> (por defecto <code>5</code>).</li></ul><h2 id="👁️-2-teleport-aleatorio-random-teleport" tabindex="-1">👁️ 2. Teleport Aleatorio (Random Teleport) <a class="header-anchor" href="#👁️-2-teleport-aleatorio-random-teleport" aria-label="Permalink to &quot;👁️ 2. Teleport Aleatorio (Random Teleport)&quot;">​</a></h2><ul><li><strong>Acción:</strong> Clic derecho.</li><li><strong>Comportamiento:</strong> Selecciona a un jugador activo (no staff) y te sitúa detrás de él.</li><li><strong>Blindaje:</strong> En esta versión, se ha bloqueado completamente el lanzamiento físico del ojo de ender para evitar que vuele por el mapa.</li></ul><p><img src="'+a+'" alt="Teleport Aleatorio en Vivo"></p><h2 id="📄-4-centro-de-guis-gui-hub" tabindex="-1">📄 4. Centro de GUIs (GUI Hub) <a class="header-anchor" href="#📄-4-centro-de-guis-gui-hub" aria-label="Permalink to &quot;📄 4. Centro de GUIs (GUI Hub)&quot;">​</a></h2><p>Al hacer clic derecho con el papel se abre un menú con dos opciones principales:</p><ol><li><strong>Reportes Pendientes:</strong> Lista interactiva con las denuncias enviadas por los usuarios.</li><li><strong>Miners / Sospecha de X-Ray:</strong> Lista de todos los jugadores que se encuentran a una coordenada Y inferior a 16 (configurable).</li></ol><h2 id="👥-5-lista-de-staff-personnel-counter" tabindex="-1">👥 5. Lista de Staff (Personnel / Counter) <a class="header-anchor" href="#👥-5-lista-de-staff-personnel-counter" aria-label="Permalink to &quot;👥 5. Lista de Staff (Personnel / Counter)&quot;">​</a></h2><ul><li><strong>Acción:</strong> Clic derecho con la cabeza de jugador.</li><li><strong>Comportamiento:</strong> Muestra el recuento de moderadores conectados y quiénes se encuentran en Modo Staff.</li></ul><p><img src="'+o+'" alt="Panel de Miembros del Staff"></p><h2 id="📊-7-test-de-clics-por-segundo-cps" tabindex="-1">📊 7. Test de Clics por Segundo (CPS) <a class="header-anchor" href="#📊-7-test-de-clics-por-segundo-cps" aria-label="Permalink to &quot;📊 7. Test de Clics por Segundo (CPS)&quot;">​</a></h2><ul><li><strong>Acción:</strong> Clic derecho sobre un jugador sospechoso de <em>autoclicker</em> o macros.</li><li><strong>Comportamiento:</strong> Durante 10 segundos registra los clics realizados. Si supera el umbral configurado (16 CPS por defecto), envía una alerta destacada en rojo al staff.</li></ul><h2 id="🧰-8-examinador-chest" tabindex="-1">🧰 8. Examinador (Chest) <a class="header-anchor" href="#🧰-8-examinador-chest" aria-label="Permalink to &quot;🧰 8. Examinador (Chest)&quot;">​</a></h2><ul><li><strong>Acción:</strong> Clic derecho sobre un jugador o ejecutando <code>/examine &lt;jugador&gt;</code>.</li><li><strong>Comportamiento:</strong> Permite ver todo el inventario, cambiar de slot e interactuar con botones directos para advertir, congelar o sancionar.</li></ul>',20)])])}const x=r(d,[["render",i]]);export{b as __pageData,x as default};
